// Generates src/data/scenario-index.js — the compact direction index that lets
// schema.js diagnose a player WITHOUT pulling the 438 KB scenario library into
// the main bundle (CA-014 / MOD-013, Wave 4).
//
// Why a generated file rather than a runtime derive: `deriveSchema` runs on the
// LOGIN path (db.js rebuilds derived state on every fetchRemoteUser), so a
// runtime derive would need the full library eagerly — which is the exact cost
// being removed. The index carries only the three fields the direction engine
// reads: `correct`, and each option's `val` + `cls`. Everything expensive (the
// hand, board, pot, villain, tableContext, fb prose) stays behind the lazy
// import, and that prose is where the weight actually is.
//
//   npm run gen:scenario-index          rewrite the file
//   npm run gen:scenario-index -- --check   exit 1 if stale (used by the gate)
//
// Staleness is a correctness bug, not a style one: an index missing a scenario
// makes directionOfHand() return null for those hands, which silently drops
// them from the diagnosis rather than failing.
import { writeFileSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
// scenarios.js gained an extensionless relative import (data/villains) when
// VILLAIN_LABELS was extracted for CA-014, so this script needs the same
// CRA-style resolution hook the other harnesses use.
import { register } from 'node:module';
register(new URL('ext-resolver.mjs', import.meta.url));
// Dynamic for the same reason as audit-scenarios.mjs: import hoisting would
// run this before register() installs the extensionless-resolution hook.
const { default: SCENARIOS } = await import('../src/data/scenarios.js');

const here = dirname(fileURLToPath(import.meta.url));
const OUT = join(here, '..', 'src', 'data', 'scenario-index.js');

const entries = SCENARIOS.map((s) => ({
  id: s.id,
  correct: s.correct,
  options: s.options.map((o) => ({ val: o.val, cls: o.cls })),
}));

// Deterministic formatting — one scenario per line keeps the diff readable and
// makes the --check comparison a plain string equality.
const body = entries
  .map((e) => `  ${JSON.stringify(e)},`)
  .join('\n');

const file = `// GENERATED by scripts/gen-scenario-index.mjs — DO NOT EDIT BY HAND.
// Run \`npm run gen:scenario-index\` after any change to scenarios.js that adds,
// removes or regrades a scenario, or changes an option's \`val\`/\`cls\`.
// \`npm run audit:scenarios\` fails if this file is stale.
//
// The direction-of-error engine (utils/schema.js) needs only these three fields
// per scenario. Keeping them here rather than importing the full library is what
// allows scenarios.js to load lazily behind "Start Session" (CA-014): the schema
// is derived on the LOGIN path, so it cannot wait for a gameplay chunk.
//
// ${entries.length} scenarios.

const SCENARIO_INDEX = [
${body}
];

export default SCENARIO_INDEX;
`;

if (process.argv.includes('--check')) {
  let current = null;
  try { current = readFileSync(OUT, 'utf8'); } catch { /* missing == stale */ }
  if (current !== file) {
    console.error('✗ src/data/scenario-index.js is STALE — run `npm run gen:scenario-index`.');
    console.error('  The direction engine reads this file; a missing scenario silently');
    console.error('  drops those hands from the diagnosis instead of erroring.');
    process.exit(1);
  }
  console.log(`✓ scenario-index.js in sync (${entries.length} scenarios)`);
} else {
  writeFileSync(OUT, file);
  console.log(`Wrote src/data/scenario-index.js — ${entries.length} scenarios.`);
}
